:root {
  --ink: #27233d;
  --paper: #fffdf6;
  --lilac: #e5ddff;
}

.cinema-card {
  width: 440px;
  padding: 16px;
  border: 2px solid var(--ink);
  border-radius: 16px;
  background: var(--paper);
  color: var(--ink);
}

.cinema-card header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.ticket-mark {
  padding: 9px;
  border-radius: 10px;
  background: var(--lilac);
  font-size: 24px;
}

.cinema-card h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1.1;
}

.screening-meta {
  margin: 4px 0 0;
  font-size: 14px;
}

.cinema-card footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 16px;
  font-size: 14px;
  font-weight: 700;
}

.cinema-card button {
  padding: 8px 12px;
  border: 0;
  border-radius: 8px;
  background: var(--ink);
  color: var(--paper);
  font-weight: 700;
}
